import React, { useState } from 'react';
import githubLogo from './images/github.jfif'; // Make sure to adjust the paths
import facebookLogo from './images/facebook.jfif';
import googleLogo from './images/google.jfif';
import appleLogo from './images/apple.jfif';

const SignIn = () => {
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('');
  const [rememberMe, setRememberMe] = useState(false); // State for the checkbox

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle sign-in logic here (e.g., API call)
    console.log('Name:', name);
    console.log('Password:', password);
    console.log('Role:', role);
    console.log('Remember Me:', rememberMe);
  };

  // Styles for the outer container
  const containerStyle = {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'flex-start', // Align to the top
    height: '100vh',
    paddingTop: '20px', // Space from the top
  };

  // Styles for the border divs
  const borderStyle = {
    borderLeft: '2px solid #ccc',
    borderRight: '2px solid #ccc',
    padding: '20px',
  };

  // Styles for the form
  const formStyle = {
    padding: '20px',
    width: '300px',
  };

  // Styles for the button
  const buttonStyle = {
    backgroundColor: 'orange', // Button color
    color: 'white', // Text color
    border: 'none',
    padding: '10px 20px',
    borderRadius: '5px',
    cursor: 'pointer',
    width: '100%', // Make button full width
    textAlign: 'center', // Center text
  };

  // Styles for the logos section
  const logosContainerStyle = {
    display: 'flex',
    justifyContent: 'space-around',
    alignItems: 'center',
    marginTop: '20px',
  };

  const logoStyle = {
    width: '40px', // Adjust logo size as needed
    height: 'auto',
  };

  return (
    <div style={containerStyle}>
      <div style={borderStyle}>
        <div style={formStyle}>
          <h2>Sign In</h2>
          <div>
            <label>Role:</label>
            <br />
            <select
              value={role}
              onChange={(e) => setRole(e.target.value)}
              required
            >
              <option value="">Select your role</option>
              <option value="user">User</option>
              <option value="admin">Admin</option>
              <option value="guest">Guest</option>
            </select>
          </div>
          <form onSubmit={handleSubmit}>
            <div>
              <label>Name:</label>
              <br />
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Enter your username"
                required
              />
            </div>
            <div>
              <label>Password:</label>
              <br />
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter your password"
                required
              />
            </div>
            <div>
              <input
                type="checkbox"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
              />
              <label> Remember Me</label>
            </div>
            <button type="submit" style={buttonStyle}>Sign In</button>
          </form>
          
          {/* Horizontal Line */}
          <hr style={{ margin: '20px 0' }} />

          {/* Logos Section */}
          <div style={logosContainerStyle}>
            <img src={githubLogo} alt="GitHub" style={logoStyle} />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>
            <img src={facebookLogo} alt="Facebook" style={logoStyle} />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>
            <img src={googleLogo} alt="Google" style={logoStyle} />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>
            <img src={appleLogo} alt="Apple" style={logoStyle} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default SignIn;
